class TestYamlDataFiles:
    """Test that YAML data files load and conform to schema expectations."""

    def _load_data(self, filename):
        with open(TEST_DATA_DIR / filename, encoding="utf-8") as f:
            return yaml.safe_load(f)

    def test_single_environment_loads(self):
        data = self._load_data("test_ingredient_with_environment.yaml")
        ingredient = data["mapped_ingredients"][0]
        assert ingredient["preferred_term"] == "Humic acid"
        ctx = ingredient["environmental_context"][0]
        assert ctx["environment_term"] == "ENVO:00000044"
        assert ctx["relevance"] == "NATURAL_SOURCE"
        assert ctx["environment_label"] == "peatland"

    def test_multiple_environments_loads(self):
        data = self._load_data("test_ingredient_multiple_environments.yaml")
        ingredient = data["mapped_ingredients"][0]
        assert ingredient["preferred_term"] == "NaCl"
        assert len(ingredient["environmental_context"]) == 3
        relevances = [ctx["relevance"] for ctx in ingredient["environmental_context"]]
        assert all(r == "ENVIRONMENT_MIMIC" for r in relevances)

    def test_no_environment_loads(self):
        data = self._load_data("test_ingredient_no_environment.yaml")
        ingredient = data["mapped_ingredients"][0]
        assert ingredient["preferred_term"] == "Agar"
        assert "environmental_context" not in ingredient

    def test_dual_relevance_loads(self):
        data = self._load_data("test_ingredient_dual_relevance.yaml")
        ingredient = data["mapped_ingredients"][0]
        assert ingredient["preferred_term"] == "Sodium sulfide"
        contexts = ingredient["environmental_context"]
        assert len(contexts) == 2
        # Same environment, different relevance
        assert contexts[0]["environment_term"] == contexts[1]["environment_term"]
        assert contexts[0]["relevance"] != contexts[1]["relevance"]
        relevances = {ctx["relevance"] for ctx in contexts}
        assert relevances == {"NATURAL_SOURCE", "REQUIRED_FOR_ORGANISM"}

    def test_all_relevance_types_covered(self):
        data = self._load_data("test_ingredient_all_relevance_types.yaml")
        all_relevances = set()
        for ingredient in data["mapped_ingredients"]:
            for ctx in ingredient.get("environmental_context", []):
                all_relevances.add(ctx["relevance"])
        expected = {
            "NATURAL_SOURCE",
            "REQUIRED_FOR_ORGANISM",
            "SELECTIVE_AGENT",
            "ENVIRONMENT_MIMIC",
            "COMMONLY_USED",
        }
        assert all_relevances == expected

    def test_all_envo_terms_valid_pattern(self):
        """Verify all ENVO terms in test data match the pattern."""
        pattern = re.compile(r"^ENVO:\d{7,8}$")
        for yaml_file in TEST_DATA_DIR.glob("*.yaml"):
            data = yaml.safe_load(yaml_file.read_text())
            for ingredient in data.get("mapped_ingredients", []):
                for ctx in ingredient.get("environmental_context", []):
                    term = ctx["environment_term"]
                    assert pattern.match(term), (
                        f"Invalid ENVO term '{term}' in {yaml_file.name}"
                    )


class TestCanonicalSchemaEnvironmentalContext:
    """Test that the canonical mediaingredientmech.yaml schema (IngredientRecord)
    carries an equivalent environmental_context definition to the legacy
    mapped_ingredients_schema.yaml (MappedIngredient).

    The two schemas must stay in sync so cross-repo tooling can treat both
    instance shapes interchangeably.
    """

    def setup_method(self):
        self.schema = load_canonical_schema()
        self.classes = self.schema["classes"]
        self.enums = self.schema["enums"]

    def test_envo_prefix_defined(self):
        assert self.schema["prefixes"]["ENVO"] == "http://purl.obolibrary.org/obo/ENVO_"

    def test_ingredient_record_has_environmental_context(self):
        attrs = self.classes["IngredientRecord"]["attributes"]
        assert "environmental_context" in attrs
        assert attrs["environmental_context"]["required"] is False
        assert attrs["environmental_context"]["multivalued"] is True
        assert attrs["environmental_context"]["range"] == "EnvironmentContext"
        assert attrs["environmental_context"]["inlined_as_list"] is True

    def test_environment_context_class_exists(self):
        assert "EnvironmentContext" in self.classes
        attrs = self.classes["EnvironmentContext"]["attributes"]
        assert attrs["environment_term"]["required"] is True
        assert attrs["environment_term"]["pattern"] == "^ENVO:\\d{7,8}$"
        assert attrs["relevance"]["required"] is True
        assert attrs["relevance"]["range"] == "EnvironmentRelevanceEnum"
        assert attrs["environment_label"]["required"] is False
        assert attrs["notes"]["required"] is False

    def test_environment_relevance_enum_matches_legacy(self):
        canonical_values = set(
            self.enums["EnvironmentRelevanceEnum"]["permissible_values"].keys()
        )
        legacy_values = set(
            load_mapped_schema()["enums"]["EnvironmentRelevanceEnum"][
                "permissible_values"
            ].keys()
        )
        assert canonical_values == legacy_values, (
            "Canonical and legacy EnvironmentRelevanceEnum must stay in sync"
        )

    def test_environment_context_class_matches_legacy_shape(self):
        legacy_attrs = load_mapped_schema()["classes"]["EnvironmentContext"][
            "attributes"
        ]
        canonical_attrs = self.classes["EnvironmentContext"]["attributes"]
        # Same attribute names with same required/range/pattern semantics.
        assert set(legacy_attrs.keys()) == set(canonical_attrs.keys())
        for name in legacy_attrs:
            for key in ("required", "range", "pattern"):
                if key in legacy_attrs[name]:
                    assert legacy_attrs[name].get(key) == canonical_attrs[name].get(
                        key
                    ), f"EnvironmentContext.{name}.{key} differs between schemas"

"""Claim assessments are typed, backward-compatible and never defaulted."""

from pathlib import Path

import pytest
from linkml.validator import Validator
from linkml.validator.plugins import JsonschemaValidationPlugin
from linkml_runtime.utils.schemaview import SchemaView

ROOT = Path(__file__).resolve().parents[1]
SCHEMA = ROOT / "src/mediaingredientmech/schema/mediaingredientmech.yaml"
CLASSES = ["MappingEvidence", "ComponentEvidence"]
SUPPORT = {"SUPPORT", "REFUTE", "PARTIAL", "NO_EVIDENCE", "WRONG_STATEMENT"}
SOURCES = {
    "FIELD_STUDY",
    "MESOCOSM",
    "LABORATORY",
    "IN_VITRO",
    "IN_VIVO",
    "COMPUTATIONAL",
    "META_ANALYSIS",
    "REVIEW",
    "REMOTE_SENSING",
    "LONG_TERM_MONITORING",
    "EXPERT_OPINION",
    "DATABASE",
    "OTHER",
}
REQUIRED = {
    "MappingEvidence": {"supports": False, "evidence_source": False},
    "ComponentEvidence": {"supports": False, "evidence_source": False},
}


@pytest.fixture(scope="module")
def assessment_view():
    return SchemaView(str(SCHEMA))


@pytest.fixture(scope="module")
def assessment_validator():
    return Validator(str(SCHEMA), validation_plugins=[JsonschemaValidationPlugin(closed=True)])


def baseline(view, cls):
    values = {
        "reference": "PMID:12345678",
        "snippet": "A verbatim test fixture passage.",
        "explanation": "Fixture assessment, not a curated scientific assertion.",
        "source": "fixture",
        "supports": "SUPPORT",
        "evidence_source": "IN_VITRO",
    }
    result = {}
    for slot in view.class_induced_slots(cls):
        if slot.required:
            if slot.name in values:
                result[slot.name] = values[slot.name]
            elif slot.range in view.all_enums():
                result[slot.name] = next(iter(view.get_enum(slot.range).permissible_values))
            else:
                raise AssertionError(f"Add an explicit fixture for {cls}.{slot.name}")
    return result


@pytest.mark.parametrize("cls", CLASSES)
def test_assessments_preserve_legacy_requiredness_and_have_no_default(
    assessment_view, assessment_validator, cls
):
    for name in ("supports", "evidence_source"):
        slot = assessment_view.induced_slot(name, cls)
        assert bool(slot.required) == REQUIRED[cls][name]
        assert slot.ifabsent is None
        expected = SUPPORT if name == "supports" else SOURCES
        assert set(assessment_view.get_enum(slot.range).permissible_values) == expected
    old = baseline(assessment_view, cls)
    assert not list(assessment_validator.iter_results(old, target_class=cls))


@pytest.mark.parametrize("cls", CLASSES)
@pytest.mark.parametrize("support", sorted(SUPPORT))
def test_all_support_assessments_validate(assessment_view, assessment_validator, cls, support):
    data = {**baseline(assessment_view, cls), "supports": support, "evidence_source": "DATABASE"}
    assert not list(assessment_validator.iter_results(data, target_class=cls))


@pytest.mark.parametrize("cls", CLASSES)
@pytest.mark.parametrize("source", sorted(SOURCES))
def test_study_types_validate_without_changing_support(
    assessment_view, assessment_validator, cls, source
):
