"""Required checks must report on every PR and its actual merge queue candidate."""

import os
import re
import subprocess
from copy import deepcopy
from pathlib import Path

import pytest
import yaml

ROOT = Path(__file__).resolve().parents[1]
VALIDATOR_PIN = (ROOT / "scripts" / ".vendored_canon_ref").read_text().strip()
# Job/check names are an external ruleset contract. Renames require coordinated
# settings changes; deriving this list from the workflows would hide a deletion.
REQUIRED_JOBS = {
    "curation-history.yaml": {"history": "history"},
    "instruction-refs.yaml": {"instruction-refs": "instruction-refs"},
    "label-correspondence.yaml": {"id-label-gate": "id-label-gate"},
    "qc-component-partonomy.yaml": {"qc": "qc-component-partonomy"},
    "qc-duplicate-ids.yaml": {"qc": "qc-duplicate-ids"},
    "qc-evidence.yaml": {"qc": "qc-evidence"},
    "qc-flat-coverage.yaml": {"qc": "qc-flat-coverage"},
    "qc-roundtrip.yaml": {"roundtrip": "roundtrip"},
    "qc-sssom.yaml": {"qc": "qc-sssom"},
    "quality.yaml": {"check": "check"},
    "tests.yaml": {"pytest": "pytest"},
    "validate-strict.yaml": {"validate-strict": "validate-strict"},
    "vendored-sync.yaml": {"vendored-sync": "vendored-sync"},
}


def _load(name):
    return yaml.safe_load((ROOT / ".github" / "workflows" / name).read_text())


def _assert_required_workflow(document, expected_jobs):
    events = document.get("on", document.get(True, {}))
    assert "pull_request" in events, "missing PR trigger"
    assert events["pull_request"] in (None, {}), "required PR checks cannot be filtered"
    assert events.get("merge_group") == {"types": ["checks_requested"]}, "missing queue trigger"
    for job_id, check_name in expected_jobs.items():
        job = document["jobs"][job_id]
        assert job.get("name", job_id) == check_name, "required check renamed"
        assert "if" not in job, "required job cannot skip the candidate"
        assert not job.get("continue-on-error"), "required job must fail on errors"
        for step in job.get("steps", []):
            if step.get("uses", "").startswith("actions/checkout@"):
                options = step.get("with", {})
                if options.get("repository") == "CultureBotAI/culturebotai-claw":
                    assert re.fullmatch(r"[0-9a-f]{40}", VALIDATOR_PIN)
                    assert options.get("ref") == "${{ steps.claw-pin.outputs.ref }}", "validator must read the consumer pin"
                    assert options.get("path") == "claw", "validator must be separate"
                    pin_steps = [other for other in job["steps"] if other.get("id") == "claw-pin"]
                    assert len(pin_steps) == 1, "validator needs exactly one pin reader"
                    assert job["steps"].index(pin_steps[0]) < job["steps"].index(step), "read pin before checkout"
                    assert any(
                        other.get("uses", "").startswith("actions/checkout@")
                        and other.get("with") == {"path": "mech", "persist-credentials": False}
                        for other in job["steps"]
                    ), "validator requires the separate event-bound MIM candidate"
                else:
                    assert options.get("repository") in (None, "${{ github.repository }}")
                    assert "ref" not in options, "must check out the event's candidate"
    concurrency = document.get("concurrency")
    if concurrency:
        assert "github.run_id" in concurrency["group"], "queue runs need distinct groups"
        assert concurrency["cancel-in-progress"] == "${{ github.event_name == 'pull_request' }}"


@pytest.mark.parametrize("workflow", REQUIRED_JOBS)
def test_required_workflow_runs_for_pr_and_merge_group(workflow):
    _assert_required_workflow(_load(workflow), REQUIRED_JOBS[workflow])


@pytest.mark.parametrize("defect", ["queue", "paths", "skip", "cancel", "checkout"])
def test_the_guard_rejects_a_broken_workflow(defect):
    name = "vendored-sync.yaml"
    document = _load(name)
    _assert_required_workflow(document, REQUIRED_JOBS[name])  # unmutated control
    broken = deepcopy(document)
    events = broken.get("on", broken.get(True))
    job = broken["jobs"]["vendored-sync"]
    if defect == "queue":
        del events["merge_group"]
    elif defect == "paths":
        events["pull_request"] = {"paths": ["src/**"]}
    elif defect == "skip":
        job["if"] = "github.event_name == 'pull_request'"
    elif defect == "cancel":
        broken["concurrency"]["cancel-in-progress"] = True
    else:
        job["steps"][0]["with"] = {"ref": "main"}
    with pytest.raises(AssertionError):
        _assert_required_workflow(broken, REQUIRED_JOBS[name])


def test_required_job_names_are_unambiguous():
    names = [
        _load(workflow)["jobs"][job_id].get("name", job_id)
        for workflow, jobs in REQUIRED_JOBS.items()
        for job_id in jobs
    ]
    assert len(names) == len(set(names)), "different required workflows report the same check"


@pytest.mark.parametrize("defect", ["unpinned", "mutable", "hardcoded", "overlap", "candidate-ref", "pin-order", "pin-reader"])
def test_evidence_validator_cannot_drift_or_replace_candidate(defect):
    name = "qc-evidence.yaml"
    document = _load(name)
    _assert_required_workflow(document, REQUIRED_JOBS[name])
    broken = deepcopy(document)
    steps = broken["jobs"]["qc"]["steps"]
    candidate, validator = [step for step in steps if step.get("uses", "").startswith("actions/checkout@")]
    if defect == "unpinned":
        del validator["with"]["ref"]
    elif defect == "mutable":
        validator["with"]["ref"] = "main"
    elif defect == "hardcoded":
        validator["with"]["ref"] = VALIDATOR_PIN
    elif defect == "overlap":
        validator["with"]["path"] = candidate["with"]["path"]
    elif defect in {"pin-order", "pin-reader"}:
        reader = next(step for step in steps if step.get("id") == "claw-pin")
        steps.remove(reader)
        if defect == "pin-order":
            steps.append(reader)
    else:
        candidate["with"]["ref"] = "main"
    with pytest.raises(AssertionError):
        _assert_required_workflow(broken, REQUIRED_JOBS[name])


def _run_evidence_pin_reader(root, pin):
    path = root / "mech/scripts/.vendored_canon_ref"
    path.parent.mkdir(parents=True)
    if pin is not None:
        path.write_bytes(pin)
    reader = next(step for step in _load("qc-evidence.yaml")["jobs"]["qc"]["steps"]
                  if step.get("id") == "claw-pin")
    output = root / "github-output"
    result = subprocess.run(
        ["bash", "-c", reader["run"]], cwd=root, capture_output=True, text=True,
        env={**os.environ, "GITHUB_OUTPUT": str(output)}, timeout=15,
    )
    return result, output


def test_evidence_pin_reader_uses_each_actual_consumer_pin(tmp_path):
    for index, pin in enumerate([b"a" * 40 + b"\n", b"b" * 40]):
        result, output = _run_evidence_pin_reader(tmp_path / str(index), pin)
        assert result.returncode == 0, result.stderr
        assert output.read_text() == "ref=" + pin.decode().strip() + "\n"


@pytest.mark.parametrize("pin", [None, b"main\n", b"A" * 40, b"a" * 40 + b"\nother=x"])
def test_evidence_pin_reader_rejects_missing_mutable_or_malformed_pin(tmp_path, pin):
    result, output = _run_evidence_pin_reader(tmp_path, pin)
    assert result.returncode != 0
    assert not output.exists()

"""Merge tombstones must resolve to their own merge target (#799).

`docs/LABEL_INDEX_CONTRACT.md` tells consumers to follow REJECTED rows, because
a merged record's `identifier` points at its merge target. Four tombstones from
the 2026-09-21 review kept the identity the review had rejected instead, so
`NaNO` resolved to the nano unit prefix. `scripts/fix_tombstone_pointers.py`
(#360) repairs exactly that, but nothing ran it after those merges; CultureMech
refused the label index outright, which blocked its pin refresh. These tests
make MIM refuse it first.
"""

from __future__ import annotations

import contextlib
import csv
import importlib.util
import io
import re
from pathlib import Path

import pytest
import yaml

ROOT = Path(__file__).resolve().parents[1]
LOADER = getattr(yaml, "CSafeLoader", yaml.SafeLoader)
_CURIE = r"([A-Za-z][\w.\-]*:[^\s,;'\"()]+)"
# Every wording a MERGED_INTO event uses for its target (#809).
MERGE_TARGET_PATTERNS = (
    re.compile(r"^Merged into " + _CURIE),
    re.compile(r"^Merged into '[^']*' on " + _CURIE),
    re.compile(r"into the existing " + _CURIE),
)


def _merge_target(text: str) -> str | None:
    for pattern in MERGE_TARGET_PATTERNS:
        match = pattern.search(text)
        if match:
            return match.group(1)
    return None


@pytest.fixture(scope="module")
def records() -> list[dict]:
    return [
        yaml.load(path.read_text(encoding="utf-8"), Loader=LOADER)
        for group in ("mapped", "unmapped")
        for path in sorted((ROOT / "data/ingredients" / group).glob("*.yaml"))
    ]


def _tombstones(records):
    for r in records:
        history = r.get("curation_history") or []
        if r.get("mapping_status") == "REJECTED" and any(
            e.get("action") == "MERGED_INTO" for e in history
        ):
            yield r, history


def test_every_merge_tombstone_points_at_a_live_record(records):
    live = {r["identifier"] for r in records if r.get("mapping_status") == "MAPPED"}
    dangling = sorted(
        (r["preferred_term"], r["identifier"])
        for r, _history in _tombstones(records)
        if not str(r["identifier"]).startswith("UNMAPPED_") and r["identifier"] not in live
    )
    assert not dangling, f"merge tombstones on an identity no live record holds: {dangling}"


def test_every_merge_tombstone_points_at_its_own_merge_target(records):
    """Liveness alone would accept a tombstone pointing at the wrong live record
    (#807). The target is the CURIE its last MERGED_INTO event names, unless a
    later REPOINTED_TOMBSTONE_IDENTIFIER event followed the winner elsewhere."""
    wrong, unparsed = [], []
    for r, history in _tombstones(records):
        target = None
        for event in history:
            text = str(event.get("changes", ""))
            if event.get("action") == "MERGED_INTO":
                target = _merge_target(text)
            elif event.get("action") == "REPOINTED_TOMBSTONE_IDENTIFIER" and " -> " in text:
                target = text.split(" -> ", 1)[1].split()[0]
        if target is None:
            unparsed.append(r["preferred_term"])
        elif target != r["identifier"]:
            wrong.append((r["preferred_term"], r["identifier"], target))
    # A new wording must be added above rather than silently skipped (#809).
    assert not unparsed, f"MERGED_INTO target not parseable: {unparsed}"
    assert not wrong, f"tombstones not on their merge target: {wrong}"


def test_no_tombstone_advertises_a_term_its_survivor_does_not_hold(records):
    """The second #360 invariant: a tombstone's ontology_id agrees with its
    survivor, so nothing indexing by ontology_id routes through a rejected term."""
    live = {r["identifier"]: r for r in records if r.get("mapping_status") == "MAPPED"}
    stale = []
    for r, _history in _tombstones(records):
        own = (r.get("ontology_mapping") or {}).get("ontology_id")
        survivor = live.get(r["identifier"])
        theirs = ((survivor or {}).get("ontology_mapping") or {}).get("ontology_id")
        if own and theirs and own != theirs:
            stale.append((r["preferred_term"], own, theirs))
    assert not stale, f"tombstones advertising a term their survivor does not hold: {stale}"


def test_published_rejected_rows_resolve_to_a_live_identifier():
    """The consumer-side check CultureMech applies to every pin (#260)."""
    with (ROOT / "docs/data/label_index.csv").open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    live = {row["identifier"] for row in rows if row["mapping_status"] == "MAPPED"}
    dangling = sorted(
        {
            row["identifier"]
            for row in rows
            if row["mapping_status"] == "REJECTED"
            and not row["identifier"].startswith("UNMAPPED_")
            and row["identifier"] not in live
        }
    )
    assert not dangling


@pytest.mark.parametrize(
    ("term", "old", "target"),
    [
        ("NaNO", "NCIT:C54713", "CHEBI:63005"),
        ("Atrazin", "cas:1924-24-9", "CHEBI:15930"),
        ("EDTA (chelating agent)", "NCIT:C360", "CHEBI:4735"),
        ("Sodium phosphate dibasic", "CHEBI:37583", "CHEBI:34683"),
    ],
)
def test_the_799_tombstones_record_what_they_used_to_assert(records, term, old, target):
    record = next(r for r in records if r["preferred_term"] == term)
    assert record["identifier"] == target
    assert record["mapping_status"] == "REJECTED"
    repoints = [
        e for e in record["curation_history"]
        if e.get("action") == "REPOINTED_TOMBSTONE_IDENTIFIER" and "(#799)" in str(e.get("changes"))
    ]
    assert len(repoints) == 1
    assert str(repoints[0]["changes"]).startswith(f"identifier {old} -> {target} ")


def test_repointer_has_nothing_left_to_do():
    """Re-running #360's repair on the committed corpus must be a no-op."""
    spec = importlib.util.spec_from_file_location(
        "fix_tombstone_pointers", ROOT / "scripts/fix_tombstone_pointers.py"
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        module.main([])
    assert "0 identifier(s) repointed, 0 ontology_id(s) refreshed" in out.getvalue()

"""Tests for the ontology_label canonicalization logic.

`scripts/correct_stale_ontology_labels.py` rewrites stale/empty
`ontology_mapping.ontology_label` values to the canonical OBO label. These pin
the decision logic (`needs_correction`) with a stub resolver so it stays
CI-safe (no OAK sqlite needed) and can't silently regress its guards.
"""

import importlib.util
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent.parent / "src"))

_spec = importlib.util.spec_from_file_location(
    "correct_stale_ontology_labels",
    Path(__file__).parent.parent / "scripts" / "correct_stale_ontology_labels.py",
)
mod = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(mod)

# stub canonical-label resolver: only CHEBI:1 and CHEBI:2 "exist".
CANON = {"CHEBI:1": "coenzyme M", "CHEBI:2": "acetate"}


def resolve(oid):
    return CANON.get(oid)


def test_stale_label_corrected():
    om = {"ontology_id": "CHEBI:1", "ontology_label": "2-Mercaptoethanesulfonate", "ontology_source": "CHEBI"}
