class TestMappingQualityAssessment:
    """Test logic for assessing mapping quality from different evidence sources."""

    def _assess_quality(self, evidence_list):
        """Simulate mapping quality assessment from evidence."""
        if not evidence_list:
            return "PROVISIONAL"

        has_db_match = any(e["evidence_type"] == "DATABASE_MATCH" for e in evidence_list)
        has_curator = any(e["evidence_type"] == "CURATOR_JUDGMENT" for e in evidence_list)
        has_llm = any(e["evidence_type"] == "LLM_SUGGESTION" for e in evidence_list)
        max_confidence = max((e.get("confidence_score", 0) for e in evidence_list), default=0)

        if has_db_match and max_confidence >= 0.95:
            return "EXACT_MATCH"
        if has_db_match and max_confidence >= 0.8:
            return "SYNONYM_MATCH"
        if has_curator:
            return "MANUAL_CURATION"
        if has_llm and has_curator:
            return "LLM_ASSISTED"
        if has_llm:
            return "LLM_ASSISTED"
        return "CLOSE_MATCH"

    def test_exact_match_from_high_confidence_db(self):
        evidence = [{"evidence_type": "DATABASE_MATCH", "confidence_score": 1.0}]
        assert self._assess_quality(evidence) == "EXACT_MATCH"

    def test_synonym_match_from_medium_confidence_db(self):
        evidence = [{"evidence_type": "DATABASE_MATCH", "confidence_score": 0.85}]
        assert self._assess_quality(evidence) == "SYNONYM_MATCH"

    def test_manual_curation(self):
        evidence = [{"evidence_type": "CURATOR_JUDGMENT", "confidence_score": 1.0}]
        assert self._assess_quality(evidence) == "MANUAL_CURATION"

    def test_llm_assisted(self):
        evidence = [{"evidence_type": "LLM_SUGGESTION", "confidence_score": 0.9}]
        assert self._assess_quality(evidence) == "LLM_ASSISTED"

    def test_provisional_no_evidence(self):
        assert self._assess_quality([]) == "PROVISIONAL"

    def test_combined_evidence(self):
        evidence = [
            {"evidence_type": "LLM_SUGGESTION", "confidence_score": 0.85},
            {"evidence_type": "CURATOR_JUDGMENT", "confidence_score": 0.95},
        ]
        quality = self._assess_quality(evidence)
        assert quality == "MANUAL_CURATION"

    def test_quality_values_in_schema(self):
        schema = load_schema()
        valid = set(schema["enums"]["MappingQualityEnum"]["permissible_values"].keys())
        test_cases = [
            [{"evidence_type": "DATABASE_MATCH", "confidence_score": 1.0}],
            [{"evidence_type": "DATABASE_MATCH", "confidence_score": 0.85}],
            [{"evidence_type": "CURATOR_JUDGMENT", "confidence_score": 1.0}],
            [{"evidence_type": "LLM_SUGGESTION", "confidence_score": 0.9}],
            [],
        ]
        for ev in test_cases:
            result = self._assess_quality(ev)
            assert result in valid, f"Quality {result} not in schema enum"

"""Navigation snapshots must agree with their declared immutable observations."""

import csv
import subprocess
from pathlib import Path

import pytest
import yaml

ROOT = Path(__file__).resolve().parents[1]
ROUND = ROOT / "reviews/reconciliation/20261011T023739Z-all-mim"


def read_tsv(name):
    with (ROUND / name).open() as stream:
        return list(csv.DictReader(stream, delimiter="\t"))


@pytest.fixture(scope="module")
def snapshot():
    records = read_tsv("records.tsv")
    current = read_tsv("current-findings.tsv")
    paths = {r["review_yaml"] for r in records + current}
    documents = {p: yaml.load((ROOT / p).read_bytes(), Loader=yaml.CSafeLoader) for p in paths}
    return records, current, documents


def test_original_record_index_is_exact_disjoint_snapshot(snapshot):
    records, _, documents = snapshot
    assert len(records) == len({r["path"] for r in records})
    expected = {}
    for path in {r["review_yaml"] for r in records}:
        d = documents[path]
        for target in d["targets"]:
            assert target["path"] not in expected
            findings = [f for f in d["findings"] if target["target_id"] in f["target_ids"]]
            expected[target["path"]] = (
                path,
                target["target_id"],
                sum(f["status"] == "open" for f in findings),
                sum(f["status"] == "deferred" for f in findings),
            )
    assert {
        r["path"]: (
            r["review_yaml"],
            r["target_id"],
            int(r["open_findings"]),
            int(r["deferred_findings"]),
        )
        for r in records
    } == expected


def test_archived_review_bases_match_saved_provenance(snapshot):
    _, _, documents = snapshot
    sources = {d["source"]["git_revision"] for d in documents.values()}
    for row in read_tsv("provenance-bases.tsv"):
        assert row["git_revision"] in sources
        assert row["retained_ref"].startswith("refs/tags/review-source/")
        result = subprocess.run(
            ["git", "rev-parse", "--verify", row["retained_ref"] + "^{commit}"],
            cwd=ROOT,
            check=True,
            text=True,
            capture_output=True,
        )
        assert result.stdout.strip() == row["git_revision"]


def test_current_index_preserves_exact_heads_and_target_scope(snapshot):
    _, current, documents = snapshot
    occurrences = {}
    for path, d in documents.items():
        for finding in d["findings"]:
            key = (d["repository"].lower(), d["review_id"], finding["finding_id"])
            assert key not in occurrences
            occurrences[key] = (path, d, finding)
    replaced = set()
    for _, d, finding in occurrences.values():
        for previous in finding.get("previous_occurrences", []):
            key = (previous["repository"].lower(), previous["review_id"], previous["finding_id"])
            _, old, predecessor = occurrences[key]
            assert predecessor["issue_key"] == finding["issue_key"]
            assert set(predecessor["target_ids"]) <= set(finding["target_ids"])
            assert old["finished_at"] <= d["started_at"]
            replaced.add(key)
    heads = {key: value for key, value in occurrences.items() if key not in replaced}
    # Keep multiple heads if a future snapshot contains competing observations.
    assert len(current) == len(heads)
    expected = {}
    for path, d, f in heads.values():
        targets = {t["target_id"]: t for t in d["targets"]}
        expected[(path, f["finding_id"])] = (
            f["issue_key"],
            f["status"],
            f["severity"],
            f["title"],
            "|".join(targets[t]["path"] for t in f["target_ids"]),
            "|".join(x["path"] for x in f["owner_paths"]),
            "|".join(f.get("external_issues", [])),
        )
    assert {
        (r["review_yaml"], r["finding_id"]): (
            r["issue_key"],
            r["status"],
            r["severity"],
            r["title"],
            r["paths"],
            r["owner_paths"],
            r["existing_issues"],
        )
        for r in current
    } == expected

