            "identifier": "CHEBI:1",
            "name": "salt hydrate",
            "mapping_status": "MAPPED",
            "ontology_source": "CHEBI",
            "ontology_id": "CHEBI:1",
            "ontology_label": "salt hydrate",
            "mapping_quality": "EXACT_MATCH",
